// PLACEHOLDER para C-11
// Este nodo deberá recibir el siguiente paciente en lista de espera y enviarle una notificación.

const paciente = $input.all()[0].json;

if (!paciente || !paciente.id) {
  return [{
    json: {
      text: 'No hay pacientes en lista de espera.',
      paciente: null
    }
  }];
}

return [{
  json: {
    chat_id: paciente.telegram_id,
    text: `Se liberó un turno!\n\nFecha: ${paciente.fecha_solicitada}\nHora: ${paciente.hora_preferida}\n\n¿Querés reservarlo?`,
    inline_buttons: [
      { text: 'Reservar turno', callback_data: `reservar_lista_${paciente.id}` },
      { text: 'No, gracias', callback_data: `rechazar_lista_${paciente.id}` }
    ]
  }
}];
